using RabbitMqRoutingLab;using Xunit;public sealed class BrokerTests
{[Theory][InlineData("order.*","order.placed",true)][InlineData("order.#","order.eu.placed",true)][InlineData("billing.*","order.placed",false)]public void Topic_matching(string p,string k,bool expected)=>Assert.Equal(expected,TopicExchange.Matches(p,k));[Fact]public void Publish_routes_to_every_matching_queue(){var x=new TopicExchange();var a=new QueueState("a");var b=new QueueState("b");x.Bind("order.*",a);x.Bind("#",b);Assert.Equal(2,x.Publish(new(Guid.NewGuid(),"order.placed","x")));Assert.Equal(1,a.Ready);Assert.Equal(1,b.Ready);}[Fact]public void Ack_removes_inflight_message(){var q=new QueueState("q");var m=new Message(Guid.NewGuid(),"a","b");q.Enqueue(m);q.Deliver();q.Ack(m.Id);Assert.Equal(0,q.Unacked);}[Fact]public void Nack_with_requeue_makes_message_ready(){var q=new QueueState("q");var m=new Message(Guid.NewGuid(),"a","b");q.Enqueue(m);q.Deliver();q.Nack(m.Id,true);Assert.Equal(1,q.Ready);}}
